const message=(text,error=false)=>{$('status').textContent=text;$('status').classList.toggle('error',error);};
const nameSchool=id=>schools.find(s=>s.id===id)?.name||'Escola';
const schoolOptions=(list,first='Selecione a escola')=>`<option value="">${esc(first)}</option>`+list.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.school_year}</option>`).join('');
const roles=()=>context.central||context.schools.length>0;
async function run(control,action){if(control?.dataset.busy)return;const revision=epoch;if(control)control.dataset.busy='1';const buttons=control?.tagName==='FORM'?[...control.querySelectorAll('button')]:[];buttons.forEach(b=>b.disabled=true);try{return await action(revision);}catch(e){if(revision===epoch)message(friendly(e),true);}finally{if(control){delete control.dataset.busy;buttons.forEach(b=>b.disabled=false);}}}
function navigation(){
 $('servicos').innerHTML=Object.entries(SERVICES).map(([id,title])=>`<a class="service ${service===id?'active':''}" href="?servico=${id}" ${service===id?'aria-current="page"':''} data-service-tab="${id}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]}</svg><span>${esc(title)}</span></a>`).join('');
 $('servicos').querySelectorAll('[data-service-tab]').forEach(a=>a.onclick=e=>{e.preventDefault();service=a.dataset.serviceTab;workspace='public';accessMode='guardian';registering=false;const url=new URL(location.href);url.searchParams.set('servico',service);url.searchParams.delete('escola');url.searchParams.delete('acesso');url.hash='';history.pushState(null,'',url);navigation();authUI();void render();});
}
function workspaceUI(){
 const dashboard=workspace==='staff'||workspace==='profile'||!!user&&service==='matricula',view=workspace==='staff'?(context.central||accessMode==='central'?'central':'staff'):'guardian';
 document.body.classList.toggle('education-system',dashboard||service==='matricula');document.body.classList.toggle('education-dashboard',dashboard);document.body.dataset.educationView=view;
 $('edu-system-hero').hidden=!dashboard;$('edu-system-hero').innerHTML=dashboard?banner(view,!!user&&(view==='central'?context.central:view==='staff'?context.central||context.schools.includes(selectedSchool):true)):'';
 $('edu-header-actions').hidden=!user;$('edu-open-management').hidden=!user||!roles();$('edu-my-account').innerHTML=icon('person')+'Minha conta';$('edu-logout').innerHTML=icon('logout')+'Sair';
 for(const [id,tab] of [['public-tab','public'],['mine-tab','mine'],['staff-tab','staff'],['profile-tab','profile']])$(id).setAttribute('aria-pressed',String(workspace===tab));
 $('public-tab').innerHTML=icon('file')+(dashboard?'Nova pré-matrícula':'Solicitar serviço');$('mine-tab').innerHTML=icon('folder')+'Meus protocolos';$('profile-tab').innerHTML=icon('person')+'Minha conta';
 $('profile-tab').hidden=!dashboard||view!=='guardian';$('staff-tab').hidden=dashboard&&view==='guardian'&&!roles();$('staff-tab').setAttribute('aria-label',context.central?'Painel da Educação':'Área das escolas');$('public-tab').parentElement.hidden=dashboard&&view!=='guardian';
 $('account').hidden=!user;$('identity').textContent=user?.email||'';$('auth').hidden=!!user||workspace==='public'&&['eventos','noticias'].includes(service);$('public-area').hidden=workspace!=='public';$('mine-area').hidden=workspace!=='mine';$('staff-area').hidden=workspace!=='staff';$('profile-area').hidden=workspace!=='profile';
 const art=$('matriculas-2027');if(art)art.hidden=dashboard||service!=='matricula';
}
async function render(){workspaceUI();if(workspace!=='public')++slotEpoch;if(workspace==='profile')return profile();if(workspace==='mine')return mine();if(workspace==='staff')return staff();return publicService();}
function unavailable(){return unavailableState(ready,schools);}
function profile(){const root=$('profile-area');if(!user){root.innerHTML='<p class="empty">Entre na sua conta para continuar.</p>';return;}root.innerHTML=`<h2>${icon('person')}Minha conta</h2><dl><dt>Nome</dt><dd>${esc(user.user_metadata?.full_name||'Nome não informado')}</dd><dt>E-mail</dt><dd>${esc(user.email)}</dd></dl><p>Seus pedidos ficam vinculados a esta conta. O vínculo de escola ou da Secretaria é concedido pela administração.</p><div class="actions"><button type="button" class="edu-blue" id="profile-protocols">${icon('folder')}Meus protocolos</button>${roles()?'<button type="button" class="secondary" id="profile-staff">Área de atendimento</button>':''}<a href="../esic/redefinir-senha/">Alterar ou recuperar minha senha</a></div>`;$('profile-protocols').onclick=()=>{workspace='mine';void render();};if($('profile-staff'))$('profile-staff').onclick=()=>{$('staff-tab').click();};}
async function recent(){const target=$('parent-recent-list'),rev=epoch;if(!target||!user)return;try{const rows=await svc.mine();if(rev!==epoch||!target.isConnected)return;target.innerHTML=recentRequests(rows,schools);target.querySelectorAll('[data-my-protocol]').forEach(b=>b.onclick=()=>{workspace='mine';workspaceUI();$('lookup').elements.protocol.value=b.dataset.myProtocol;void mine(b.dataset.myProtocol);});}catch{if(rev===epoch&&target.isConnected)target.innerHTML='<p class="empty">Não foi possível carregar seus pedidos. Tente consultar em Meus protocolos.</p>';}}

function authUI(){
 const school=accessMode==='school',central=accessMode==='central',form=$('login');
 $('auth-title').textContent=registering?'Crie sua conta':school?'Acesso da equipe de atendimento':central?'Acesso da Secretaria de Educação':'Acesso dos pais e responsáveis';
 $('auth-description').textContent=registering?'Informe seus dados pessoais. A conta da equipe precisa ser vinculada antes de acessar uma escola.':school?'Informe o ID da escola, seu e-mail e sua senha.':central?'Use a conta autorizada para gerenciar as unidades da rede.':'Crie sua conta ou entre para cadastrar o aluno e acompanhar a pré-matrícula.';
 document.querySelectorAll('[data-access-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accessMode===accessMode)));
 $('access-help').textContent=school?'O ID identifica a escola; somente pessoas vinculadas pela administração acessam seus atendimentos.':central?'O cadastro de uma conta não concede permissão administrativa. O acesso da Secretaria é liberado pelo administrador principal.':'Cada responsável usa seu próprio e-mail e senha. Os pedidos ficam vinculados à sua conta.';
 for(const [id,name] of [['registration-name','full_name'],['registration-confirmation','confirmation']]){$(id).hidden=!registering;form.elements[name].disabled=!registering;form.elements[name].required=registering;}
 $('school-login-field').hidden=!school||registering;form.elements.school_id.disabled=!school||registering;form.elements.school_id.required=school&&!registering;
 if(selectedSchool)form.elements.school_id.value=selectedSchool;
 form.elements.password.autocomplete=registering?'new-password':'current-password';form.elements.password.minLength=registering?8:1;
 $('auth-submit').value=registering?'signup':'login';$('auth-submit').textContent=registering?'Cadastrar minha conta':'Entrar';$('create-account').hidden=registering;$('cancel-registration').hidden=!registering;$('resend-confirmation').hidden=registering;
}
function accessModeUI(mode){accessMode=mode;registering=false;workspace=mode==='guardian'?'public':'staff';staffTab=mode==='central'?'overview':'requests';history.replaceState(null,'',authRedirect());authUI();void render();}
function schoolGate(){const root=$('staff-content');root.innerHTML=`<div class="school-access-gate"><h2>Acesso por ID da escola</h2><p>Informe o ID enviado pela Secretaria. Sua conta precisa estar vinculada a essa unidade.</p>${selectedSchool?'<p class="school-access-error">Esta conta não está vinculada ao ID informado.</p>':''}<form id="school-access-form" class="form"><label>ID da escola<input name="school_id" required maxlength="36" autocomplete="off" spellcheck="false" value="${esc(selectedSchool)}"></label><div class="actions"><button>Acessar minha escola</button></div></form></div>`;const form=$('school-access-form');form.onsubmit=e=>{e.preventDefault();void run(form,async()=>{selectedSchool=schoolAccess(context,form.elements.school_id.value);history.replaceState(null,'',schoolAccessURL(selectedSchool,location.href));await staff();});};}

async function publicService(){
 const root=$('public-area'),revision=++slotEpoch;
 if(service==='noticias'||service==='eventos'){root.innerHTML='<section class="card"><div class="section-title"><span class="step">◫</span><div><h2>'+esc(SERVICES[service])+'</h2><p>Informações oficiais da Educação.</p></div></div><div id="public-list" class="public-list">Carregando…</div></section>';return publicContent(revision);}
 root.innerHTML=service==='matricula'&&user?`<div class="edu-parent-workspace"><section class="card edu-parent-card"><h2>${icon('person')}Cadastrar aluno</h2><div id="service-form-area"></div></section>${guide()}</div><section class="card edu-recent"><h2>${icon('file')}Meus pedidos</h2><div id="parent-recent-list">Carregando seus pedidos…</div></section>`:`<section class="card"><div class="section-title"><span class="step">02</span><div><h2>${esc(SERVICES[service])}</h2><p>${service==='matricula'?'Solicite a pré-matrícula e organize o atendimento na escola.':'Envie sua solicitação diretamente à equipe da escola.'}</p></div></div>${service==='matricula'?'<p class="notice">A pré-matrícula e o agendamento não garantem vaga. A confirmação depende da documentação e da disponibilidade da escola.</p>':''}<div id="service-form-area"></div></section>`;
 if(service==='matricula'&&user)void recent();
 if(service==='alimentacao'){root.insertAdjacentHTML('beforeend','<section class="card"><h2>Cardápios publicados pelas escolas</h2><div id="menu-list" class="public-list">Carregando cardápios…</div></section>');void menus(revision);}
 const area=$('service-form-area'),active=schools.filter(s=>s.active&&(service!=='matricula'||s.enrollment_open));
 if(!ready||!active.length){area.innerHTML=unavailable();return;}
 if(!user){area.innerHTML='<p class="empty">Entre na sua conta acima para preencher o formulário. Seus dados e o acompanhamento ficarão protegidos.</p>';return;}
 const student=['matricula','transporte'].includes(service);
 area.innerHTML=service==='matricula'?enrollmentForm(schoolOptions(active)):`<form id="request-form" class="form"><fieldset><legend>1. Escola e atendimento</legend><label>Escola<select name="school_id" id="school" required>${schoolOptions(active)}</select></label><div id="school-summary" class="school-summary" hidden></div>${service==='matricula'?'<div class="grid"><label>Etapa de ensino<select name="stage" id="stage" required disabled><option value="">Escolha a escola primeiro</option></select></label><label>Ano ou série<select name="grade" id="grade" required disabled><option value="">Escolha a etapa primeiro</option></select></label></div>':''}</fieldset><fieldset><legend>2. ${student?'Aluno e responsável':'Contato para o atendimento'}</legend><div class="grid">${student?'<label class="full">Nome completo do aluno<input name="student_name" required minlength="3" maxlength="160" autocomplete="off"></label>':''}${service==='matricula'?`<label>Data de nascimento do aluno<input name="birth_date" type="date" required max="${localDate()}" autocomplete="off"></label>`:''}<label>Nome completo do responsável<input name="guardian_name" required minlength="3" maxlength="160" autocomplete="name"></label><label>Telefone com DDD<input name="phone" type="tel" inputmode="tel" required maxlength="20" autocomplete="tel" placeholder="(87) 99999-9999"></label>${student?'<label class="full">Rua e bairro, ou sítio/comunidade rural<input name="address" required minlength="5" maxlength="500" autocomplete="street-address"></label>':''}${service==='transporte'?`<label>Turno<select name="shift" required><option value="">Selecione</option>${opts(SHIFTS)}</select></label><label>Ponto de embarque e referência<input name="pickup_point" required minlength="5" maxlength="500" placeholder="Informe onde o aluno precisa embarcar"></label>`:''}</div></fieldset>${service==='matricula'?'<fieldset><legend>3. Agendamento na escola</legend><label>Horário de atendimento<select name="slot_id" id="slot" disabled><option value="">Escolha a escola primeiro</option></select></label><p id="slot-help" class="hint">Horários de Manari–PE. O agendamento reserva um atendimento, não uma vaga escolar.</p></fieldset>':''}<label>${service==='matricula'?'Observação para a escola (opcional)':'Descreva sua solicitação'}<textarea name="details" maxlength="6000" rows="4" ${service==='matricula'||service==='transporte'?'':'required minlength="10"'} placeholder="Não inclua senhas, CPF ou informações de saúde neste campo."></textarea></label>${service==='infraestrutura'?'<label>Foto do problema (opcional)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><span class="hint">Até 5 MB. Evite fotografar alunos ou documentos pessoais.</span></label>':''}<label class="checkbox"><input name="acknowledge" type="checkbox" required><span>Confirmo os dados e estou ciente de que serão usados para este atendimento pela escola e pela Secretaria de Educação.${service==='matricula'?' Entendo que o pedido não garante vaga.':''}</span></label><div class="actions"><button type="submit">${service==='matricula'?'Enviar pré-matrícula':'Enviar solicitação'}</button></div></form>`;
 const form=$('request-form');if(user.user_metadata?.full_name)form.elements.guardian_name.value=user.user_metadata.full_name;let key=crypto.randomUUID();
 $('school').onchange=async()=>{
  const school=active.find(s=>s.id===$('school').value),token=++slotEpoch;
  $('school-summary').hidden=!school;$('school-summary').innerHTML=schoolSummary(school);
  if(service!=='matricula')return;
  $('stage').innerHTML='<option value="">Selecione a etapa</option>'+opts(Object.fromEntries((school?.stages||[]).map(v=>[v,STAGES[v]])));$('stage').disabled=!school;$('grade').innerHTML='<option value="">Escolha a etapa primeiro</option>';$('grade').disabled=true;
  $('slot').innerHTML='<option value="">Carregando horários…</option>';$('slot').disabled=true;if(!school){$('slot').innerHTML='<option value="">Escolha a escola primeiro</option>';return;}
  try{const rows=(await svc.slots(school.id)).filter(s=>s.booked<s.capacity);if(token!==slotEpoch||!$('slot'))return;$('slot').innerHTML='<option value="">Enviar pré-matrícula sem agendamento</option>'+rows.map(s=>`<option value="${s.id}">${esc(date(s.starts_at))} · ${s.capacity-s.booked} atendimento(s) disponível(is)</option>`).join('');$('slot').disabled=false;$('slot-help').textContent=rows.length?'Escolha um horário ou envie a pré-matrícula para aguardar orientação. Horário de Manari–PE.':'Ainda não há horários disponíveis. Você pode enviar a pré-matrícula e aguardar a escola pelo acompanhamento do protocolo.';}catch(e){if(token===slotEpoch){$('slot').innerHTML='<option value="">Não foi possível carregar os horários</option>';$('slot-help').textContent='Selecione a escola novamente para tentar carregar a agenda.';message(friendly(e),true);}}
 };
 if(service==='matricula')$('stage').onchange=()=>{const grades=GRADES[$('stage').value]||[];$('grade').innerHTML='<option value="">Selecione o ano ou série</option>'+opts(Object.fromEntries(grades.map(v=>[v,v])));$('grade').disabled=!grades.length;};
 form.onsubmit=e=>{e.preventDefault();void run(form,async rev=>{const f=new FormData(form),photo=f.get('photo');if(photo?.size)validatePhoto(photo);const input={...Object.fromEntries(f),service,request_key:key};delete input.photo;delete input.acknowledge;const row=await svc.submit(input);if(rev!==epoch)return;let appointment=null;if(row.slot_id){const result=await client.from('edu_slots').select('starts_at,ends_at').eq('id',row.slot_id).maybeSingle();appointment=result.data;}if(rev!==epoch)return;const selectedSchool=schools.find(s=>s.id===row.school_id);let warning='';if(photo?.size){try{await svc.upload(row,photo);}catch{warning='O pedido foi registrado, mas a foto não foi enviada. Anexe a foto em Meus protocolos.';}}if(rev!==epoch)return;key=crypto.randomUUID();area.innerHTML=`<div class="success" role="status"><strong>${row.slot_id?'Atendimento agendado':'Solicitação recebida'}</strong><p class="protocol">${esc(row.protocol)}</p><p>Escola: ${esc(nameSchool(row.school_id))} · Ano letivo ${row.school_year}</p><p>Local: ${esc(selectedSchool?.address||'Consulte a escola.')}</p>${directionsLink(selectedSchool)}${row.slot_id?`<p>Atendimento: ${appointment?esc(date(appointment.starts_at))+' · horário de Manari–PE':'consulte o horário em Meus protocolos.'}</p>`:'<p>Sem horário reservado. Aguarde a orientação da escola pelo protocolo.</p>'}${selectedSchool?.instructions?`<p class="school-summary">Documentos e orientações: ${esc(selectedSchool.instructions)}</p>`:'<p>Confira com a escola os documentos necessários para o atendimento.</p>'}<p>Acompanhe a situação e as orientações em Meus protocolos.${service==='matricula'?' A vaga depende da confirmação da escola.':''}</p>${warning?`<p class="notice">${esc(warning)}</p>`:''}<div class="actions"><button type="button" id="see-request">Acompanhar meu pedido</button><button type="button" id="print-receipt" class="secondary">Imprimir comprovante</button></div></div>`;$('see-request').onclick=()=>{workspace='mine';void render();};$('print-receipt').onclick=()=>window.print();message('Solicitação registrada. Guarde o protocolo.');area.scrollIntoView({block:'center',behavior:'smooth'});});};
}
async function menus(revision){const list=$('menu-list');try{const rows=ready?await svc.notices('cardapio'):[];if(revision!==slotEpoch||!list?.isConnected)return;list.innerHTML=rows.length?rows.map(n=>`<article class="request"><span class="eyebrow">${n.school_id?esc(nameSchool(n.school_id)):'Toda a rede'}</span><h3>${esc(n.title)}</h3><small>Publicado em ${date(n.created_at)}</small><p class="body-copy">${esc(n.body)}</p></article>`).join(''):'<p class="empty">Ainda não há cardápios publicados pelas escolas.</p>';}catch{if(list?.isConnected)list.innerHTML='<p class="empty">Não foi possível carregar os cardápios. Selecione o serviço novamente para tentar.</p>';}}
async function publicContent(revision){
 const list=$('public-list');try{const rows=service==='noticias'?await svc.news():ready?await svc.notices('evento'):[];if(revision!==slotEpoch||!list.isConnected)return;
 const items=service==='eventos'?rows.filter(n=>!n.event_at||new Date(n.event_at)>=new Date()):rows;
 list.innerHTML=items.length?items.map(n=>`<article class="request"><span class="eyebrow">${service==='noticias'?'EDUCAÇÃO E CULTURA':n.school_id?esc(nameSchool(n.school_id)):'SECRETARIA DE EDUCAÇÃO'}</span><h3>${esc(n.title)}</h3><small>${date(n.publish_at||n.event_at||n.created_at)}</small>${safeURL(n.image_url)?`<img class="image" src="${esc(safeURL(n.image_url))}" alt="${esc(n.title)}" loading="lazy">`:''}<p class="body-copy">${esc(n.body||n.summary)}</p>${service==='eventos'&&n.registration_open?`<button data-register-event="${n.id}">Solicitar inscrição</button>`:''}</article>`).join(''):`<div class="empty">${service==='noticias'?'Ainda não há publicações da Educação.':'Ainda não há eventos publicados para este período.'}</div>`;
 list.querySelectorAll('[data-register-event]').forEach(b=>b.onclick=()=>eventForm(items.find(n=>n.id===b.dataset.registerEvent)));
 }catch(e){if(revision===slotEpoch&&list.isConnected){list.innerHTML='<div class="empty">Não foi possível carregar. <button id="retry-content">Tentar novamente</button></div>';$('retry-content').onclick=()=>publicContent(revision);message(friendly(e),true);}}
}
function eventForm(event){if(!user){$('auth').hidden=false;message('Entre na sua conta para solicitar a inscrição.');$('auth').scrollIntoView({block:'start',behavior:'smooth'});return;}
 const root=$('public-area'),eligible=schools.filter(s=>s.active&&(!event.school_id||s.id===event.school_id));if(!eligible.length){message('Nenhuma escola está disponível para este evento.',true);return;}
 root.innerHTML=`<section class="card"><h2>${esc(event.title)}</h2><p>${date(event.event_at)}</p><p class="notice">A inscrição será analisada pela equipe. A participação depende da confirmação.</p><form id="event-form" class="form"><label>Escola<select name="school_id" required>${schoolOptions(eligible)}</select></label><label>Nome do responsável ou participante adulto<input name="guardian_name" required minlength="3" maxlength="160"></label><label>Telefone com DDD<input name="phone" type="tel" required maxlength="20"></label><label class="checkbox"><input type="checkbox" required>Estou ciente de que a solicitação será analisada pela equipe.</label><button>Enviar solicitação de inscrição</button></form></section>`;let key=crypto.randomUUID();const form=$('event-form');form.onsubmit=e=>{e.preventDefault();void run(form,async rev=>{await svc.submit({...Object.fromEntries(new FormData(form)),service:'evento',notice_id:event.id,request_key:key});if(rev!==epoch)return;workspace='mine';message('Solicitação de inscrição recebida. Acompanhe em Meus protocolos.');await render();});};}
async function mine(protocol=''){const sequence=++mineSequence;$('mine-list').replaceChildren();if(!user){$('mine-list').innerHTML='<p class="empty">Entre na sua conta para consultar seus protocolos.</p>';return;}await run($('mine-area'),async rev=>{const rows=await svc.mine(protocol);if(rev!==epoch||sequence!==mineSequence)return;await renderRequests($('mine-list'),rows,false);message(rows.length?`${rows.length} pedido(s) encontrado(s).`:'Nenhum pedido encontrado para sua conta.');});}
async function renderRequests(root,rows,staffMode){
 const cache=new Map();const slotsFor=id=>{if(!cache.has(id))cache.set(id,svc.slots(id));return cache.get(id);};
 root.innerHTML=rows.length?rows.map(r=>`<article class="request" data-request="${r.id}"><span class="protocol">${esc(r.protocol)}</span><h3>${esc(r.service==='evento'?'Inscrição em evento':SERVICES[r.service])}</h3><p><strong>${esc(nameSchool(r.school_id))}</strong> · Ano letivo ${r.school_year}</p><span class="badge">${esc(STATUS[r.status])}</span><p>${esc(r.student_name||r.guardian_name)}</p><small>Enviado em ${date(r.created_at)}</small>${directionsLink(schools.find(s=>s.id===r.school_id))}<details data-details="${r.id}"><summary>Ver dados e orientações</summary><dl>${[['Responsável',r.guardian_name],['Telefone',r.phone],['Endereço',r.address],['Data de nascimento',r.birth_date?new Date(r.birth_date+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}):''],['Etapa',STAGES[r.stage]],['Ano/série',r.grade],['Turno',SHIFTS[r.shift]],['Ponto de embarque',r.pickup_point],['Relato',r.details]].filter(x=>x[1]).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div data-slot-info></div><div class="edu-history-block"><h4>Histórico e orientações</h4><div data-history>Carregando…</div></div>${r.service==='infraestrutura'?'<div data-photos></div>':''}${r.service==='infraestrutura'&&r.user_id===user.id&&r.status!=='cancelado'?'<form data-upload class="inline screen-only"><label>Anexar foto do problema<input type="file" name="photo" required accept="image/jpeg,image/png,image/webp"></label><button>Enviar foto</button></form>':''}${r.service==='matricula'?'<p class="notice">A pré-matrícula e o agendamento não garantem vaga. A escola analisa a documentação e a disponibilidade.</p>':''}</details>${staffMode&&r.status!=='cancelado'?`<form data-action class="form screen-only"><label>Situação<select name="status">${opts(Object.fromEntries((r.service==='matricula'?['recebido','agendado','documentos_pendentes','confirmado','aguardando_vaga','cancelado']:['recebido','em_analise','documentos_pendentes','resolvido','cancelado']).map(v=>[v,STATUS[v]])),r.status)}</select></label>${r.service==='matricula'?'<label>Horário para agendar ou reagendar<select name="slot"><option value="">Manter horário atual</option></select></label>':''}<label>Orientação ao responsável<textarea name="note" required minlength="5" maxlength="2000" placeholder="A orientação aparecerá no acompanhamento do responsável."></textarea></label><button>Salvar atendimento</button></form>`:!staffMode&&!['cancelado','confirmado','resolvido'].includes(r.status)?'<details class="screen-only"><summary>Cancelar minha solicitação</summary><p>O horário reservado será liberado e o pedido permanecerá no histórico.</p><form data-cancel class="form"><label>Motivo do cancelamento<textarea name="note" required minlength="5" maxlength="2000"></textarea></label><button class="secondary">Confirmar cancelamento do pedido</button></form></details>':''}</article>`).join(''):'<p class="empty">Nenhum pedido encontrado.</p>';
 for(const r of rows){const card=root.querySelector(`[data-request="${r.id}"]`);let loaded=false;card.querySelector('[data-details]').ontoggle=async e=>{if(!e.currentTarget.open||loaded)return;const rev=epoch;try{const events=await svc.history(r.id);if(rev!==epoch||!card.isConnected)return;card.querySelector('[data-history]').innerHTML='<ol class="timeline">'+events.map(h=>`<li><strong>${esc(STATUS[h.status]||h.status)}</strong><small>${date(h.created_at)}</small><p>${esc(h.note)}</p></li>`).join('')+'</ol>';if(r.slot_id){const {data,error}=await client.from('edu_slots').select('starts_at,ends_at').eq('id',r.slot_id).maybeSingle();if(error)throw error;if(rev!==epoch)return;if(data)card.querySelector('[data-slot-info]').textContent='Agendamento: '+date(data.starts_at)+' · horário de Manari–PE.';}
 if(r.service==='infraestrutura'){const links=await svc.attachments(r);if(rev!==epoch)return;card.querySelector('[data-photos]').innerHTML=links.length?'<h4>Fotos do problema</h4><div class="photo-links">'+links.map((f,i)=>`<a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">Abrir foto ${i+1}</a>`).join('')+'</div>':'<p class="hint">Nenhuma foto anexada.</p>';}
 loaded=true;}catch(e){if(rev===epoch){card.querySelector('[data-history]').textContent='Não foi possível carregar. Feche e abra novamente para tentar.';message(friendly(e),true);}}};
 const form=card.querySelector('[data-action]');if(form){form.onsubmit=e=>{e.preventDefault();void run(form,async rev=>{const f=new FormData(form);await svc.act(r.id,String(f.get('status')),String(f.get('note')),f.get('slot'));if(rev!==epoch)return;message('Atendimento atualizado.');await queue();if(context.central)void statistics();});};if(r.service==='matricula'){try{const slots=await slotsFor(r.school_id);if(!card.isConnected)return;form.elements.slot.innerHTML='<option value="">Manter horário atual</option>'+slots.filter(s=>s.booked<s.capacity||s.id===r.slot_id).map(s=>`<option value="${s.id}">${esc(date(s.starts_at))}${s.id===r.slot_id?' · atual':''}</option>`).join('');}catch{if(card.isConnected){form.elements.slot.innerHTML='<option value="">Não foi possível carregar a agenda</option>';form.elements.slot.disabled=true;form.insertAdjacentHTML('afterbegin','<p class="notice">A agenda não carregou. Atualize a fila para reagendar. Você ainda pode registrar orientações sem alterar o horário.</p>');}}}}

 const cancel=card.querySelector('[data-cancel]');if(cancel)cancel.onsubmit=e=>{e.preventDefault();void run(cancel,async rev=>{await svc.act(r.id,'cancelado',String(new FormData(cancel).get('note')));if(rev!==epoch)return;message('Pedido cancelado e horário liberado.');await mine();});};
 const upload=card.querySelector('[data-upload]');if(upload)upload.onsubmit=e=>{e.preventDefault();void run(upload,async rev=>{const file=new FormData(upload).get('photo');validatePhoto(file);await svc.upload(r,file);if(rev!==epoch)return;message('Foto enviada.');await mine();});};
 }
}
async function staff(){
 const root=$('staff-content');root.replaceChildren();if(!user){root.innerHTML='<section class="card"><h2>Área de atendimento</h2><p>Entre na sua conta acima para acessar as unidades autorizadas.</p></section>';return;}
 if(!ready){root.innerHTML=unavailable();return;}
 if(accessMode==='central'&&!context.central){root.innerHTML='<section class="card"><h2>Secretaria de Educação</h2><p>Esta conta não possui acesso à Central. Solicite autorização ao administrador principal.</p></section>';return;}
 if(!context.central&&(!selectedSchool||!context.schools.includes(selectedSchool)))return schoolGate();
 if(!roles()){root.innerHTML='<p class="empty">Esta conta não possui vínculo com a Educação.</p>';return;}
 const permitted=scopedSchools(schools,context,context.central?'':selectedSchool);
 const tabs=context.central?{overview:'Visão geral',schools:'Cadastro de escolas',slots:'Agenda',requests:'Pedidos da rede',notices:'Cardápios e eventos',...(context.admin?{members:'Equipe e acessos'}:{})}:{requests:'Solicitações',slots:'Agenda',history:'Histórico',notices:'Cardápios e eventos'};
 if(!Object.hasOwn(tabs,staffTab))staffTab='requests';
 root.innerHTML=`${context.central?`<section class="edu-metrics" id="edu-metrics" aria-label="Resumo da rede">${metrics({schools:schools.length})}</section>`:`<section class="card edu-unit-context"><strong>${icon('check')}Acesso restrito às unidades autorizadas</strong><label>Escola vinculada<select id="staff-unit">${scopedSchools(schools,context).map(s=>`<option value="${esc(s.id)}" ${s.id===selectedSchool?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label></section>`}<nav class="staff-tabs" aria-label="Painel da Educação">${Object.entries(tabs).map(([id,title])=>`<button type="button" class="${id===staffTab?'selected':''}" data-staff-tab="${id}" aria-pressed="${id===staffTab}">${icon(id==='slots'?'calendar':id==='schools'?'school':id==='members'?'person':'file')}${esc(title)}</button>`).join('')}</nav><div id="staff-body"></div><p class="edu-system-note">${icon('info')}${context.central?'A Secretaria acompanha todas as escolas. Cada equipe acessa apenas as unidades autorizadas.':'O retorno aparece em Meus protocolos para o responsável.'}</p>`;
 root.querySelectorAll('[data-staff-tab]').forEach(b=>b.onclick=()=>{++queueSequence;staffTab=b.dataset.staffTab;queuePage=0;selectedRequest='';void staff();});
 if($('staff-unit'))$('staff-unit').onchange=()=>{selectedSchool=schoolAccess(context,$('staff-unit').value);++queueSequence;selectedRequest='';queuePage=0;history.replaceState(null,'',schoolAccessURL(selectedSchool,location.href));void staff();};
 if(context.central)void statistics();
 await run(root,async()=>{
  if(['requests','history'].includes(staffTab)){
   const b=$('staff-body');b.innerHTML=`<div class="edu-queue-layout"><section class="card edu-queue-list-card"><h2>${icon('file')}${staffTab==='history'?'Histórico de atendimentos':'Fila de atendimento'}</h2><form id="queue-filters" class="inline"><label>Buscar protocolo<input name="protocol" maxlength="40" placeholder="Informe o protocolo completo"></label><label>Escola<select name="school">${schoolOptions(permitted,context.central?'Todas as escolas':'Minha escola')}</select></label><label>Serviço<select name="service"><option value="">Todos os serviços</option>${opts(Object.fromEntries(Object.entries(SERVICES).filter(([k])=>!['eventos','noticias'].includes(k)).concat([['evento','Inscrição em evento']])))}</select></label><label>Situação<select name="status"><option value="">Todas as situações</option>${opts(STATUS)}</select></label><button type="submit" class="edu-blue">Filtrar solicitações</button></form><p id="queue-total" class="hint" role="status"></p><div id="queue-list" class="edu-queue-items"></div><div class="pager"><button id="prev" class="secondary" type="button">Anterior</button><span id="queue-page"></span><button id="next" class="secondary" type="button">Próxima</button></div></section><section class="card edu-request-detail" id="request-detail-card" aria-labelledby="request-detail-title"><h2 id="request-detail-title">${icon('school')}Detalhes da solicitação</h2><div id="request-detail"><p class="empty">Selecione um pedido na fila de atendimento.</p></div></section></div>`;
   if(!context.central){$('queue-filters').elements.school.value=selectedSchool;$('queue-filters').elements.school.disabled=true;}
   $('queue-filters').onsubmit=e=>{e.preventDefault();queuePage=0;selectedRequest='';void run($('queue-filters'),queue);};$('prev').onclick=()=>{queuePage=Math.max(0,queuePage-1);void run(b,queue);};$('next').onclick=()=>{queuePage++;void run(b,queue);};await queue();
  }else if(staffTab==='schools')await schoolAdmin();else if(staffTab==='slots'){await slotAdmin();$('staff-body').classList.add('card');}else if(staffTab==='notices'){await noticeAdmin();$('staff-body').classList.add('card');}else if(staffTab==='members'){await memberAdmin();$('staff-body').classList.add('card');}else await overview();
 });
}
async function statistics(){const target=$('edu-metrics'),rev=epoch;if(!target)return;try{const data=await svc.statistics();if(rev!==epoch||!target.isConnected)return;target.innerHTML=metrics({schools:schools.length,...data});}catch{if(rev===epoch&&target.isConnected)target.insertAdjacentHTML('afterend','<p class="hint">Não foi possível carregar os totais. Selecione outra aba para tentar novamente.</p>');}}
async function overview(){const root=$('staff-body');root.innerHTML=`<section class="card"><div class="edu-section-head"><h2>${icon('school')}Escolas da rede</h2><button type="button" id="overview-new-school">+ Cadastrar escola</button></div>${schoolTable(schools)}</section><section class="card"><h2>Organize o atendimento da rede</h2><p>Cadastre as unidades oficiais, vincule as contas autorizadas e abra a pré-matrícula no período definido pela Secretaria.</p><div class="actions"><button type="button" class="edu-blue" data-overview-tab="requests">Ver solicitações da rede</button><button type="button" class="secondary" data-overview-tab="slots">Organizar agenda</button>${context.admin?'<button type="button" class="secondary" data-overview-tab="members">Equipe e acessos</button>':''}</div></section>`;$('overview-new-school').onclick=()=>{staffTab='schools';void staff();};root.querySelectorAll('[data-overview-tab]').forEach(b=>b.onclick=()=>{staffTab=b.dataset.overviewTab;void staff();});root.querySelectorAll('[data-edit-school]').forEach(b=>b.onclick=async()=>{staffTab='schools';await staff();fillSchool(b.dataset.editSchool);});}
async function queue(){
 const rev=epoch,sequence=++queueSequence,form=$('queue-filters');if(!form)return;const f=new FormData(form);$('queue-list').innerHTML='<p class="empty">Carregando solicitações…</p>';$('request-detail').innerHTML='<p class="empty">Carregando a fila de atendimento…</p>';
 let data;try{data=await svc.queue({...Object.fromEntries(f),...(!context.central?{school:schoolAccess(context,selectedSchool)}:{}),archive:staffTab==='history',page:queuePage});}catch(e){if(rev===epoch&&sequence===queueSequence&&form.isConnected){$('queue-list').innerHTML='<p class="notice">Não foi possível carregar as solicitações. Use Filtrar solicitações para tentar novamente.</p>';$('request-detail').innerHTML='<p class="empty">Aguardando o carregamento da fila.</p>';}throw e;}
 if(rev!==epoch||sequence!==queueSequence||!form.isConnected)return;queueRows=data.rows;$('queue-total').textContent=`${data.count} pedido(s) encontrado(s)`;$('queue-page').textContent=`Página ${queuePage+1} de ${Math.max(1,Math.ceil(data.count/25))}`;$('prev').disabled=queuePage===0;$('next').disabled=(queuePage+1)*25>=data.count;
 selectedRequest=queueRows.some(r=>r.id===selectedRequest)?selectedRequest:queueRows[0]?.id||'';drawQueue();if(selectedRequest)await openRequest(selectedRequest,false);else $('request-detail').innerHTML='<p class="empty">Nenhum pedido disponível para estes filtros.</p>';
}
function drawQueue(){$('queue-list').innerHTML=queueItems(queueRows,selectedRequest,schools);$('queue-list').querySelectorAll('[data-open-request]').forEach(b=>b.onclick=()=>void run(b,()=>openRequest(b.dataset.openRequest,true)));}
async function openRequest(id,scroll){const row=queueRows.find(r=>r.id===id);if(!row||!$('request-detail'))return;selectedRequest=id;drawQueue();const target=$('request-detail'),rev=epoch;await renderRequests(target,[row],true);if(rev!==epoch||!target.isConnected||selectedRequest!==id)return;const details=target.querySelector('[data-details]');if(details)details.open=true;const historyBlock=target.querySelector('.edu-history-block');if(historyBlock)target.querySelector('.request').append(historyBlock);if(scroll&&window.matchMedia('(max-width:720px)').matches)$('request-detail-card').scrollIntoView({behavior:'smooth',block:'start'});}
function fillSchool(id){const s=schools.find(s=>s.id===id),form=$('school-form');if(!s||!form)return;for(const key of ['id','name','address','contact','school_year','instructions','maps_url'])form.elements[key].value=s[key]??'';for(const key of ['active','enrollment_open'])form.elements[key].checked=s[key];form.querySelectorAll('[name=stages]').forEach(x=>x.checked=s.stages.includes(x.value));refreshLocationPreview(form);$('school-access-information').hidden=false;$('school-access-id').value=s.id;$('school-access-url').value=schoolAccessURL(s.id,location.href);form.scrollIntoView({block:'start',behavior:'smooth'});}
async function schoolAdmin(){
 const b=$('staff-body');b.innerHTML=`<section class="card"><div class="edu-section-head"><h2>${icon('school')}Escolas da rede</h2><button type="button" id="add-school">+ Cadastrar escola</button></div>${schoolTable(schools)}</section><div class="edu-management-grid"><section class="card"><h3>${icon('school')}Dados da unidade</h3><p class="hint">Use os dados oficiais. O ID é gerado ao salvar. Ative a unidade e abra a pré-matrícula somente no período autorizado.</p><form id="school-form" class="form"><input name="id" type="hidden"><div class="grid"><label class="full">Nome oficial da escola<input name="name" required minlength="3" maxlength="160"></label><label class="full">Endereço<input name="address" required minlength="5" maxlength="500"></label><label>Ano letivo<input name="school_year" type="number" min="2020" max="2100" value="2027" required></label><label>Contato institucional<input name="contact" maxlength="160"></label></div>${locationFields()}<fieldset><legend>Etapas atendidas</legend><div class="checks">${Object.entries(STAGES).map(([v,n])=>`<label><input type="checkbox" name="stages" value="${v}">${n}</label>`).join('')}</div><p class="hint">Preencha as etapas antes de abrir a pré-matrícula. O cadastro pode ser salvo com essa informação pendente enquanto a pré-matrícula estiver fechada.</p></fieldset><label>Documentos e orientações<textarea name="instructions" maxlength="4000"></textarea></label><div class="checks"><label><input type="checkbox" name="active">Escola ativa</label><label><input type="checkbox" name="enrollment_open">Pré-matrícula aberta</label></div><div class="actions"><button type="submit">Salvar escola</button><button id="new-school" type="button" class="secondary">Limpar</button></div></form><div id="school-access-information" class="school-access-tools" hidden><label>ID da escola<input id="school-access-id" readonly></label><label>Link de acesso da equipe<input id="school-access-url" readonly></label><p class="hint">A pessoa responsável cria e confirma sua conta; o administrador vincula o e-mail à escola. O ID não substitui a senha.</p></div></section><section class="card" id="school-members-panel">${context.admin?'<p>Carregando equipe e acessos…</p>':'<h3>Equipe e acessos</h3><span class="edu-status">Somente administrador</span><p>Solicite ao administrador principal o vínculo da conta confirmada de cada responsável à escola autorizada.</p>'}</section></div>`;
 const form=$('school-form');bindLocationPreview(form);function clear(){form.reset();form.elements.id.value='';$('school-access-information').hidden=true;refreshLocationPreview(form);}
 $('new-school').onclick=clear;$('add-school').onclick=()=>{clear();form.scrollIntoView({block:'start',behavior:'smooth'});};b.querySelectorAll('[data-edit-school]').forEach(button=>button.onclick=()=>fillSchool(button.dataset.editSchool));
 form.onsubmit=e=>{e.preventDefault();void run(form,async rev=>{const f=new FormData(form),p={...Object.fromEntries(f),stages:f.getAll('stages'),active:f.has('active'),enrollment_open:f.has('enrollment_open')};p.maps_url=mapsURL(f.get('maps_url'));if(p.enrollment_open&&!p.stages.length)throw Error('Selecione pelo menos uma etapa antes de abrir a pré-matrícula.');const saved=await svc.call('edu_save_school',{p_payload:p});if(rev!==epoch)return;schools=await svc.catalog();message('Escola salva. O ID e o link da equipe estão disponíveis abaixo.');await staff();fillSchool(saved.id);});};
 if(context.admin)try{await memberAdmin($('school-members-panel'));}catch(e){$('school-members-panel').innerHTML='<h3>Equipe e acessos</h3><p>Não foi possível carregar os vínculos. Tente novamente pela aba Equipe e acessos.</p>';message(friendly(e),true);}
}

async function slotAdmin(){const b=$('staff-body'),mineSchools=scopedSchools(schools,context,context.central?'':selectedSchool);b.innerHTML=`<h3>Agenda de atendimento</h3><p class="hint">Datas e horários de Manari–PE. Capacidade é a quantidade de atendimentos neste horário. Um horário com reservas só pode mudar de data mediante reagendamento de cada pedido.</p><form id="slot-form" class="form"><input name="id" type="hidden"><div class="grid"><label>Escola<select name="school_id" id="slot-school" required>${schoolOptions(mineSchools)}</select></label><label>Capacidade de atendimento<input name="capacity" type="number" min="1" max="100" value="1" required></label><label>Início<input name="starts_at" type="datetime-local" required></label><label>Fim<input name="ends_at" type="datetime-local" required></label></div><label class="checkbox"><input name="active" type="checkbox" checked>Horário disponível para novos agendamentos</label><div class="actions"><button>Salvar horário</button><button type="reset" class="secondary">Novo horário</button></div></form><div id="slots-list" class="request-list"></div>`;
 const form=$('slot-form');let rows=[],version=0;async function loadSlots(){const school=form.elements.school_id.value,v=++version;if(!school){$('slots-list').replaceChildren();return;}rows=await svc.slots(school);if(v!==version||!$('slots-list'))return;$('slots-list').innerHTML=rows.map(s=>`<article class="request"><h3>${esc(date(s.starts_at))}</h3><p>${s.booked} reservado(s) de ${s.capacity} · Fim: ${esc(date(s.ends_at))}</p><button class="secondary" data-edit-slot="${s.id}">Editar horário</button></article>`).join('')||'<p class="empty">Nenhum horário futuro ativo cadastrado.</p>';$('slots-list').querySelectorAll('[data-edit-slot]').forEach(x=>x.onclick=()=>{const s=rows.find(s=>s.id===x.dataset.editSlot);form.elements.id.value=s.id;form.elements.capacity.value=s.capacity;form.elements.active.checked=s.active;for(const key of ['starts_at','ends_at']){const d=new Date(s[key]);form.elements[key].value=new Date(d.getTime()-3*3600000).toISOString().slice(0,16);}form.scrollIntoView({block:'start',behavior:'smooth'});});}
 $('slot-school').onchange=()=>void run(b,loadSlots);form.onsubmit=e=>{e.preventDefault();void run(form,async rev=>{const f=new FormData(form),p={...Object.fromEntries(f),active:f.has('active')};p.starts_at=schoolTime(p.starts_at);p.ends_at=schoolTime(p.ends_at);if(new Date(p.ends_at)<=new Date(p.starts_at))throw Error('O fim deve ser depois do início.');await svc.call('edu_save_slot',{p_payload:p});if(rev!==epoch)return;form.elements.id.value='';message('Horário salvo.');await loadSlots();});};}
async function noticeAdmin(){const b=$('staff-body');const [menus,events]=await Promise.all([svc.notices('cardapio',true),svc.notices('evento',true)]),rows=[...menus,...events].filter(n=>context.central||n.school_id===selectedSchool);b.innerHTML=`<h3>Cardápios e eventos</h3><form id="notice-form" class="form"><input name="id" type="hidden"><div class="grid"><label>Tipo<select name="kind" id="notice-kind"><option value="cardapio">Cardápio escolar</option><option value="evento">Evento cultural</option></select></label><label>Escola<select name="school_id" required>${schoolOptions(scopedSchools(schools,context,context.central?'':selectedSchool),context.central?'Toda a rede (somente eventos)':'Selecione a escola')}</select></label><label class="full">Título<input name="title" required minlength="3" maxlength="160"></label><label id="notice-date-field" hidden>Data e horário do evento<input name="event_at" type="datetime-local" disabled></label></div><label>Conteúdo e orientações<textarea name="body" required minlength="10" maxlength="6000" rows="5"></textarea></label><div class="checks"><label><input name="published" type="checkbox">Publicar no portal</label><label id="notice-registration-field" hidden><input name="registration_open" type="checkbox" disabled>Abrir solicitações de inscrição</label></div><div class="actions"><button>Salvar publicação</button><button type="reset" class="secondary">Nova publicação</button></div></form><div class="request-list">${rows.map(n=>`<article class="request"><h3>${esc(n.title)}</h3><p>${n.kind==='cardapio'?'Cardápio':'Evento'} · ${n.school_id?esc(nameSchool(n.school_id)):'Toda a rede'} · ${n.published?'Publicado':'Rascunho'}</p><button data-edit-notice="${n.id}" class="secondary">Editar publicação</button></article>`).join('')||'<p class="empty">Nenhum cardápio ou evento cadastrado.</p>'}</div>`;
 const form=$('notice-form');function fields(){const event=form.elements.kind.value==='evento';$('notice-date-field').hidden=!event;$('notice-registration-field').hidden=!event;form.elements.event_at.disabled=!event;form.elements.registration_open.disabled=!event;form.elements.school_id.required=!context.central||!event;}fields();$('notice-kind').onchange=fields;form.onreset=()=>setTimeout(fields,0);
 b.querySelectorAll('[data-edit-notice]').forEach(x=>x.onclick=()=>{const n=rows.find(n=>n.id===x.dataset.editNotice);for(const key of ['id','kind','school_id','title','body'])form.elements[key].value=n[key]||'';for(const key of ['published','registration_open'])form.elements[key].checked=n[key];form.elements.event_at.value=n.event_at?new Date(new Date(n.event_at).getTime()-3*3600000).toISOString().slice(0,16):'';fields();form.scrollIntoView({block:'start',behavior:'smooth'});});
 form.onsubmit=e=>{e.preventDefault();void run(form,async rev=>{const f=new FormData(form),p={...Object.fromEntries(f),published:f.has('published'),registration_open:f.has('registration_open')};p.event_at=p.kind==='evento'&&p.event_at?schoolTime(p.event_at):null;if(p.registration_open&&!p.event_at)throw Error('Informe a data para abrir inscrições.');await svc.call('edu_save_notice',{p_payload:p});if(rev!==epoch)return;message('Publicação salva.');await staff();});};}
async function memberAdmin(b=$('staff-body')){const rev=epoch,members=await svc.call('edu_members');if(rev!==epoch||!b.isConnected)return;b.innerHTML=`<h3>${icon('person')}Equipe e acessos</h3><span class="edu-status">Somente administrador</span><p class="notice">Vincule somente responsáveis autorizados. A conta deve existir e ter e-mail confirmado. O perfil da escola acessa os pedidos apenas da unidade escolhida; a Secretaria acessa toda a rede.</p><form id="member-form" class="form"><div class="grid"><label>E-mail da conta confirmada<input name="email" type="email" required maxlength="254"></label><label>Perfil<select name="role" id="member-role"><option value="school">Equipe da escola</option><option value="central">Secretaria de Educação — toda a rede</option></select></label><label id="member-school-field">Escola<select name="school" required>${schoolOptions(schools)}</select></label></div><label class="checkbox"><input name="active" type="checkbox" checked>Acesso ativo</label><label class="checkbox"><input type="checkbox" required>Confirmo que este responsável está autorizado para o perfil selecionado.</label><button>Salvar vínculo</button></form><div class="request-list">${members.map(m=>`<article class="request"><h3>${esc(m.email)}</h3><p>${m.role==='central'?'Secretaria de Educação':esc(nameSchool(m.school_id))} · ${m.active?'Ativo':'Inativo'}</p><button class="secondary" data-member-email="${esc(m.email)}" data-member-school="${m.school_id||''}" data-member-role="${m.role}" data-member-active="${m.active}">Editar vínculo</button></article>`).join('')||'<p class="empty">Nenhum vínculo cadastrado.</p>'}</div>`;
 const form=$('member-form');function fields(){const central=form.elements.role.value==='central';$('member-school-field').hidden=central;form.elements.school.disabled=central;form.elements.school.required=!central;}$('member-role').onchange=fields;b.querySelectorAll('[data-member-email]').forEach(x=>x.onclick=()=>{form.elements.email.value=x.dataset.memberEmail;form.elements.role.value=x.dataset.memberRole;form.elements.school.value=x.dataset.memberSchool;form.elements.active.checked=x.dataset.memberActive==='true';fields();});
 form.onsubmit=e=>{e.preventDefault();void run(form,async rev=>{const f=new FormData(form);await svc.call('edu_set_member',{p_email:String(f.get('email')),p_school:f.get('role')==='central'?null:f.get('school'),p_role:String(f.get('role')),p_active:f.has('active')});if(rev!==epoch)return;message('Vínculo atualizado.');await staff();});};}
async function identity(){const rev=++epoch;++queueSequence;++mineSequence;queueRows=[];selectedRequest='';user=null;context={central:false,admin:false,schools:[]};$('mine-list').replaceChildren();$('staff-content').replaceChildren();$('public-area').replaceChildren();$('profile-area').replaceChildren();workspaceUI();const r=await client.auth.getUser();if(rev!==epoch)return;user=r.data?.user||null;
 try{schools=await svc.catalog();ready=true;}catch(e){if(rev!==epoch)return;ready=false;schools=[];message(friendly(e),true);}if(rev!==epoch)return;if(user&&ready){try{context=await svc.context();}catch(e){if(rev!==epoch)return;message(friendly(e),true);}}if(rev!==epoch)return;authUI();await render();}
$('public-tab').onclick=()=>{accessMode='guardian';registering=false;authUI();workspace='public';history.replaceState(null,'',authRedirect());void render();};$('mine-tab').onclick=()=>{accessMode='guardian';registering=false;authUI();workspace='mine';void render();};$('staff-tab').onclick=()=>{staffTab=context.central?'overview':'requests';accessMode=context.central?'central':'school';registering=false;authUI();workspace='staff';history.replaceState(null,'',authRedirect());void render();};
$('edu-open-management').onclick=()=>{$('staff-tab').click();if(!$('edu-system-hero').hidden)$('edu-system-hero').scrollIntoView({block:'start',behavior:'smooth'});};
$('profile-tab').onclick=()=>{workspace='profile';void render();};$('edu-my-account').onclick=()=>{workspace='profile';void render();};$('edu-logout').onclick=()=>{$('logout').click();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-retry-schools]');if(b)void run(b,async()=>{await identity();});});
$('lookup').onsubmit=e=>{e.preventDefault();void mine(String(new FormData(e.currentTarget).get('protocol')));};$('all-mine').onclick=()=>{$('lookup').reset();void mine();};
$('show-password').onclick=()=>{const input=$('login').elements.password;input.type=input.type==='password'?'text':'password';$('show-password').textContent=input.type==='password'?'Mostrar':'Ocultar';$('show-password').setAttribute('aria-pressed',String(input.type==='text'));};
document.querySelectorAll('[data-access-mode]').forEach(b=>b.onclick=()=>accessModeUI(b.dataset.accessMode));
$('create-account').onclick=()=>{registering=true;authUI();};$('cancel-registration').onclick=()=>{registering=false;authUI();};
const authRedirect=()=>{const u=new URL(location.href);u.search='';u.searchParams.set('servico',service);u.hash=workspace==='staff'?'gestao':'';if(accessMode==='school'&&selectedSchool)u.searchParams.set('escola',selectedSchool);if(accessMode==='central')u.searchParams.set('acesso','secretaria');return u.href;};
$('resend-confirmation').onclick=()=>{void run($('login'),async()=>{await authenticate(client,{action:'resend',email:$('login').elements.email.value},authRedirect());message('Se houver uma conta aguardando confirmação, o e-mail será reenviado. Confira também o spam.');});};
$('login').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;void run(form,async()=>{const f=new FormData(form),action=registering?'signup':'login';if(action==='login'&&accessMode==='school')selectedSchool=schoolID(f.get('school_id'));const r=await authenticate(client,{action,email:String(f.get('email')),password:String(f.get('password')),name:String(f.get('full_name')||''),confirmation:String(f.get('confirmation')||''),mode:accessMode,school:selectedSchool},authRedirect());form.elements.password.value='';form.elements.confirmation.value='';if(action==='signup'&&!r.data.session){registering=false;authUI();message('Confira seu e-mail e confirme a conta antes de entrar. O cadastro não libera acesso administrativo.');return;}registering=false;await identity();message('Conta conectada.');if(!$('edu-system-hero').hidden)$('edu-system-hero').scrollIntoView({block:'start'});});};
$('logout').onclick=()=>{selectedSchool='';void run($('account'),async()=>{++epoch;user=null;context={central:false,admin:false,schools:[]};$('mine-list').replaceChildren();$('staff-content').replaceChildren();$('public-area').replaceChildren();workspaceUI();const r=await client.auth.signOut({scope:'local'});if(r.error)throw r.error;await identity();message('Você saiu da conta.');});};
window.addEventListener('popstate',()=>{const value=new URLSearchParams(location.search).get('servico');service=Object.hasOwn(SERVICES,value)?value:'matricula';const route=accessRoute(location.href);workspace=route.workspace;accessMode=route.mode;selectedSchool=route.school;registering=false;authUI();navigation();void render();});
authUI();navigation();try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.0');const config=window.MANARI_PUBLIC_CONFIG;client=createClient(config.supabaseUrl,config.supabaseAnonKey,{auth:{storageKey:'manari-esic-auth-v1',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});svc=api(client);client.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'||event==='SIGNED_IN'&&session?.user?.id!==user?.id)setTimeout(()=>void identity(),0);});await identity();if(ready)message('Escolha um serviço para começar.');}catch(e){message(friendly(e),true);$('public-area').innerHTML=unavailable();}
